-- +goose Up

CREATE TABLE IF NOT EXISTS hr_case (
    tenant_id                tenant_ref   NOT NULL REFERENCES tenant (tenant_id),
    case_id                  uuid         NOT NULL,
    case_key                 semantic_key NOT NULL,
    case_type_ref            text NOT NULL,
    owner_ref                text NOT NULL,
    status                   text NOT NULL DEFAULT 'OPEN',
    effective_from           date         NOT NULL,
    known_at                 timestamptz  NOT NULL,
    recorded_at              timestamptz  NOT NULL DEFAULT now(),

    PRIMARY KEY (tenant_id, case_id),
    CONSTRAINT hr_case_key_unique UNIQUE (tenant_id, case_key),
    CONSTRAINT hr_case_status_check CHECK (status IN ('OPEN', 'IN_PROGRESS', 'ESCALATED', 'CLOSED', 'REOPENED')),
    CONSTRAINT hr_case_knowledge_order CHECK (known_at <= recorded_at)
);

CREATE INDEX IF NOT EXISTS hr_case_recorded
    ON hr_case (tenant_id, recorded_at DESC);

ALTER TABLE hr_case ENABLE ROW LEVEL SECURITY;
ALTER TABLE hr_case FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON hr_case
    USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
    WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
GRANT SELECT, INSERT, UPDATE ON hr_case TO hcmnext_app;

CREATE TABLE IF NOT EXISTS case_transition (
    tenant_id                tenant_ref   NOT NULL REFERENCES tenant (tenant_id),
    transition_id            uuid         NOT NULL,
    case_id                  uuid         NOT NULL,
    revision_sequence        bigint       NOT NULL,
    from_state               text NOT NULL,
    to_state                 text NOT NULL,
    reason                   text NOT NULL,
    known_at                 timestamptz  NOT NULL,
    recorded_at              timestamptz  NOT NULL DEFAULT now(),

    PRIMARY KEY (tenant_id, transition_id),
    CONSTRAINT case_transition_revision_positive CHECK (revision_sequence >= 1),
    CONSTRAINT case_transition_knowledge_order CHECK (known_at <= recorded_at),
    FOREIGN KEY (tenant_id, case_id) REFERENCES hr_case (tenant_id, case_id)
);

CREATE INDEX IF NOT EXISTS case_transition_recorded
    ON case_transition (tenant_id, recorded_at DESC);

CREATE OR REPLACE TRIGGER case_transition_append_only
    BEFORE UPDATE OR DELETE ON case_transition
    FOR EACH ROW EXECUTE FUNCTION forbid_mutation();

REVOKE UPDATE, DELETE ON case_transition FROM PUBLIC;

ALTER TABLE case_transition ENABLE ROW LEVEL SECURITY;
ALTER TABLE case_transition FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON case_transition
    USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
    WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
GRANT SELECT, INSERT ON case_transition TO hcmnext_app;

